TriggerOraclev10g.body:
DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM ATENCION a
    WHERE a.rut_medico = :NEW.rut_medico
      AND a.fecha_hora = :NEW.fecha_hora
      AND a.id_atencion != NVL(:NEW.id_atencion,-1);

  IF v_count > 0 THEN
    RAISE_APPLICATION_ERROR(-20002, 'Conflicto de agenda: el mÃ©dico ya tiene una atenciÃ³n en ese horario.');
  END IF;
END;
